<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {bluetoothExchangeWindow,bluetoothExchangeCapabilities} from './bluetooth-exchange-state.js';
 import {bluetoothExchangeMenus} from './bluetooth-exchange-menus.js';
 import {createBluetoothExchangeNativeView} from './bluetooth-exchange-native-view.js';
 import './bluetooth-exchange.css';
 let {window,state: bluetoothExchangeState,profile,windowId=window?.id,bluetooth,getFile,execute,registerView,available=true,active=true,controls={}}=$props();
 let root=$state(null),message=$state(''),pin=$state('');let originalState,originalProfile,originalWindow,originalId,retired=false,facade;
 const session=$derived(bluetoothExchangeWindow(bluetoothExchangeState,windowId)),cap=$derived(bluetoothExchangeCapabilities(profile)),source=$derived(session?.source?getFile?.(session.source.fileId):null),device=$derived(bluetooth?.devices.find(row=>row.id===session?.deviceId)),menus=$derived(bluetoothExchangeMenus({state: bluetoothExchangeState,profile,windowId,bluetooth})),menu=$derived(menus.find(row=>row.id===session?.menu)),canSend=$derived(!!source&&source.revision===session?.source?.revision&&device?.kind==='other'&&device.available&&device.paired&&bluetooth?.powered);
 function current(){return !retired&&root?.isConnected&&bluetoothExchangeState===originalState&&profile===originalProfile&&window===originalWindow&&windowId===originalId;}
 async function command(suffix,payload={}){if(!current()||!available||!active)return;const response=await execute(`bluetoothfileexchange.${suffix}`,{windowId},payload);if(current())message=response?.status==='applied'?'':response?.error?.message??'The local exchange operation is unavailable.';return response;}
 async function menuAction(item){if(!item.enabled||!item.request||!current())return;const response=await execute(item.request.command,item.request.target,item.request.payload);if(current()){message=response?.status==='applied'?'':response?.error?.message??'The menu operation is unavailable.';if(response?.status==='applied'&&session?.menu)command('sheet',{menu:null});}}
 async function pair(){pin='';await command('pair');}
 function drop(event){event.preventDefault();const one=event.dataTransfer?.getData('application/x-jesteros-file-id'),many=event.dataTransfer?.getData('application/x-jesteros-file-ids');if(one){command('choose',{fileId:one});return;}if(many){try{const ids=JSON.parse(many);if(Array.isArray(ids)&&ids.length===1&&typeof ids[0]==='string'){command('choose',{fileId:ids[0]});return;}}catch{}}message='Drop exactly one original virtual File.';}
 function keyboard(event){if(event.key==='Escape'){event.preventDefault();if(session?.sheet==='pair')command('pairConfirm',{accept:false});else command('sheet',{sheet:null,menu:null});}const modifier=cap.windows?event.ctrlKey:event.metaKey;if(modifier&&event.key.toLowerCase()==='o'){event.preventDefault();command('choose');}}
 onMount(()=>{originalState=bluetoothExchangeState;originalProfile=profile;originalWindow=window;originalId=windowId;facade=createBluetoothExchangeNativeView({getRoot:()=>root,getState:()=>bluetoothExchangeState,getProfile:()=>profile,getWindow:()=>window,windowId,available:()=>current()&&available&&active,tick});registerView?.(windowId,facade);return()=>{retired=true;pin='';facade.destroy();registerView?.(originalId,null,facade);};});
</script>
<section bind:this={root} class="bluetooth-exchange-app" class:classic={cap.classic} class:golden={cap.golden} class:windows={cap.windows} data-bluetooth-exchange-window-id={windowId} data-profile={typeof profile==='string'?profile:profile.id} role="region" aria-label={cap.label} tabindex="0" onkeydown={keyboard}>
 {#if session}
 <header class="bluetooth-exchange-titlebar">{#if !cap.windows}<WindowControls active={active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen} zoomed={controls.zoomed}/>{/if}<strong>{cap.label}</strong></header>
 {#if cap.windows||cap.golden}<p class="bluetooth-exchange-disclosure">{cap.availability}</p>{/if}
 <nav class="bluetooth-exchange-menus" aria-label="Bluetooth File Exchange menus">{#each menus as group}<button data-bluetooth-exchange-control={`menu:${group.id}`} aria-expanded={session.menu===group.id} disabled={!active||!available||!group.enabled} onclick={()=>command('sheet',{menu:session.menu===group.id?null:group.id})}>{group.label}</button>{/each}</nav>
 {#if menu}<div class="bluetooth-exchange-menu" role="menu" aria-label={menu.label}>{#each menu.children as item}<button role="menuitem" data-bluetooth-exchange-control={`menu-item:${item.id}`} disabled={!item.enabled} onclick={()=>menuAction(item)}><span>{item.label}</span><kbd>{item.shortcut??''}</kbd></button>{/each}</div>{/if}
 <div class="bluetooth-exchange-body" inert={!active||!available||!!session.sheet}>
 <header class="bluetooth-exchange-intro"><svg viewBox="0 0 48 64" aria-hidden="true"><path d="M21 3l20 18-19 17 19 17-20 7V3zM5 16l35 37M5 48l35-28"/></svg><div><h2>{cap.windows?'Send files · local equivalent':'Select a Bluetooth Device'}</h2><p>Select a fictional device to receive a genuine local File.</p></div></header>
 <div class="bluetooth-exchange-source" role="group" aria-label="Source virtual File" ondragover={event=>event.preventDefault()} ondrop={drop}><div><strong>{source?.name??'No File Selected'}</strong><small>{source?`${source.content.length} retained text units · original revision ${source.revision}`:'Choose or drop one actual virtual File'}</small>{#if session.source&&!source}<em>The original source File is unavailable.</em>{/if}</div><button data-bluetooth-exchange-control="choose" onclick={()=>command('choose')}>Choose File…</button></div>
 <div class="bluetooth-exchange-device-list" data-bluetooth-exchange-area="content" role="listbox" aria-label="Canonical shared Bluetooth devices">{#if bluetooth}{#each bluetooth.devices as row}<button role="option" aria-selected={session.deviceId===row.id} class:selected={session.deviceId===row.id} data-bluetooth-exchange-control={`device:${row.id}`} onclick={()=>command('device',{deviceId:row.id})}><span class="bluetooth-exchange-device-icon" aria-hidden="true">{row.kind==='other'?'▣':row.kind==='keyboard'?'⌨':row.kind==='trackpad'?'▱':'○'}</span><span><strong>{row.name}</strong><small>{!bluetooth.powered?'Bluetooth is off':!row.available?'Unavailable':row.paired?'Paired':'Not paired'}{row.kind!=='other'?' · no local file-transfer service':''}</small></span><span class="bluetooth-exchange-device-status">{row.paired?'✓':''}</span></button>{/each}{#if !bluetooth.devices.length}<p>No canonical Bluetooth devices are present.</p>{/if}{:else}<p>The original shared Bluetooth authority is unavailable.</p>{/if}</div>
 <div class="bluetooth-exchange-device-actions"><span>{bluetooth?.powered?'Bluetooth On · shared authority':'Bluetooth Off · change in Bluetooth settings'}</span><button data-bluetooth-exchange-control="pair" disabled={!bluetooth?.powered||!device?.available||device?.kind!=='other'} onclick={pair}>{device?.paired?'Connect / Confirm…':'Pair…'}</button></div>
 <details class="bluetooth-exchange-local-settings"><summary>Local receiver simulation</summary><p>The receiver is authored fiction, not a remote device. Accepted bytes are copied to a real local Files folder.</p><label>Destination <select data-bluetooth-exchange-control="destination" value={session.destination} onchange={event=>command('settings',{destination:event.currentTarget.value})}><option value="downloads">Downloads</option><option value="documents">Documents</option><option value="desktop">Desktop</option></select></label><label>Receiver decision <select data-bluetooth-exchange-control="receiverDecision" value={session.receiverDecision} onchange={event=>command('settings',{receiverDecision:event.currentTarget.value})}><option value="ask">Ask in this window</option><option value="accept">Automatically accept locally</option><option value="reject">Automatically decline locally</option></select></label></details>
 {#if session.phase==='awaiting'}<section class="bluetooth-exchange-acceptance" aria-label="Fictional local receiver"><strong>{device?.name} · authored local receiver</strong><p>Accept {source?.name??'the original File'} into local {session.destination}?</p><button data-bluetooth-exchange-control="receive:reject" onclick={()=>command('receive',{decision:'reject'})}>Decline</button><button data-bluetooth-exchange-control="receive:accept" onclick={()=>command('receive',{decision:'accept'})}>Accept Locally</button></section>{/if}
 <footer class="bluetooth-exchange-actions"><button data-bluetooth-exchange-control="cancel" onclick={()=>command('cancel')}>Cancel</button>{#if session.phase==='complete'}<button data-bluetooth-exchange-control="reveal" onclick={()=>command('reveal')}>Show Local Destination</button>{:else}<button class="primary" data-bluetooth-exchange-control="send" disabled={!canSend||session.phase==='awaiting'} onclick={()=>command('send')}>{cap.windows?'Next / Send Locally':'Send'}</button>{/if}</footer>
 </div>
 <div class="bluetooth-exchange-progress" data-bluetooth-exchange-progress-panel hidden><progress data-bluetooth-exchange-progress max="100" value="0" aria-label="Local transfer progress"></progress><output data-bluetooth-exchange-progress-label></output><button data-bluetooth-exchange-control="progress:cancel" onclick={()=>command('cancel')}>Cancel</button></div>
 <footer class="bluetooth-exchange-status" role="status" class:failed={session.phase==='failed'}>{message||session.status}</footer>
 {#if session.sheet}<div class="bluetooth-exchange-backdrop"><section class="bluetooth-exchange-sheet" role="dialog" aria-modal="true" aria-label={session.sheet==='pair'?'Bluetooth Pairing':'Bluetooth File Exchange Help'}>{#if session.sheet==='pair'}<h2>Pair {device?.name}?</h2><p>This is the same original device used by the shared Bluetooth settings.</p>{#if device?.pairing==='confirm'}<p>Confirm the authored fictional code:</p><output class="bluetooth-exchange-passkey">{device.passkey}</output>{:else if device?.pairing==='pin'}<label>Fictional PIN <input data-bluetooth-exchange-control="pair:pin" maxlength="6" inputmode="numeric" bind:value={pin}/></label><p>Authored pairing cue: {device.passkey}</p>{/if}<p>No host adapter or real credentials are accessed.</p><button data-bluetooth-exchange-control="pair:cancel" onclick={()=>command('pairConfirm',{accept:false})}>Cancel</button><button data-bluetooth-exchange-control="pair:confirm" onclick={()=>command('pairConfirm',{accept:true,...(device?.pairing==='pin'?{pin}:{})})}>Pair / Connect</button>{:else}<h2>{cap.label} Help</h2><p>{cap.availability}</p><p>Choose an actual virtual File, then select the canonical shared Bluetooth receiver. File-transfer support is explicitly limited to fictional devices of kind “other”; keyboards, audio routes and unavailable devices cannot receive files.</p><p>Pairing changes the same shared Bluetooth graph as Settings. Send presents an explicitly local receiver decision. Acceptance preserves all genuine original bytes in a local Files copy; rejection creates no File. Progress reflects source reading and destination preparation, not radio traffic.</p><p>No WebBluetooth, hardware discovery, remote browsing or network service is used.</p><button data-bluetooth-exchange-control="help:done" onclick={()=>command('sheet',{sheet:null})}>Done</button>{/if}</section></div>{/if}
 {:else}<p role="alert">The original Bluetooth File Exchange session is unavailable.</p>{/if}
</section>
